import com.ezylang.evalex.config.ExpressionConfiguration;
import com.ezylang.evalex.config.FunctionDictionaryIfc;
import com.ezylang.evalex.config.OperatorDictionaryIfc;
import com.ezylang.evalex.parser.Token;
import com.ezylang.evalex.parser.Tokenizer;
import com.ezylang.evalex.functions.FunctionIfc;
import com.ezylang.evalex.operators.OperatorIfc;
import com.ezylang.evalex.parser.ParseException;
import org.junit.Test;
import static org.junit.Assert.*;
import org.mockito.Mockito;
import java.util.List;

public class TokenizerTest {

    @Test
    public void parseEmptyExpressionTest() throws ParseException {
        ExpressionConfiguration config = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("", config);
        List<Token> result = tokenizer.parse();
        assertEquals(0, result.size());
    }

    @Test
    public void parseExpressionWithNumberTest() throws ParseException {
      ExpressionConfiguration config = Mockito.mock(ExpressionConfiguration.class);
      Tokenizer tokenizer = new Tokenizer("50", config);
      List<Token> result = tokenizer.parse();
      assertEquals(1, result.size());
      assertEquals(new Token(Token.TokenType.NUMERIC, "50"), result.get(0));
    }

    @Test
    public void parseExpressionWithOperatorTest() throws ParseException {
      OperatorIfc operator = Mockito.mock(OperatorIfc.class);
      FunctionIfc function = Mockito.mock(FunctionIfc.class);
      OperatorDictionaryIfc operatorDictionary = Mockito.mock(OperatorDictionaryIfc.class);
      FunctionDictionaryIfc functionDictionary = Mockito.mock(FunctionDictionaryIfc.class);
      Mockito.when(operatorDictionary.getOperator(Mockito.eq("+"))).thenReturn(operator);
      Mockito.when(functionDictionary.getFunctions()).thenReturn(new ArrayList<>());
      Mockito.when(operator.getPrecedence()).thenReturn(1);
      Mockito.when(operator.isLeftAssociativity()).thenReturn(true);

      ExpressionConfiguration config = new ExpressionConfiguration(operatorDictionary, functionDictionary);
      Tokenizer tokenizer = new Tokenizer("1+1", config);
      List<Token> result = tokenizer.parse();
      assertEquals(3, result.size());
    }

    @Test(expected = ParseException.class)
    public void parseExpressionWithInvalidCharactersTest() throws ParseException {
      ExpressionConfiguration config = Mockito.mock(ExpressionConfiguration.class);
      Tokenizer tokenizer = new Tokenizer("a+1", config);
      tokenizer.parse();
    }

    @Test
    public void parseStringLiteralDoubleQuotesTest() throws ParseException {
      ExpressionConfiguration config = Mockito.mock(ExpressionConfiguration.class);
      Tokenizer tokenizer = new Tokenizer("\"test\"", config);
      Token result = tokenizer.parseStringLiteral();
      assertEquals(new Token(Token.TokenType.LITERAL_STR, "test"), result);
    }

    @Test(expected = ParseException.class)
    public void parseStringLiteralNoClosingQuoteTest() throws ParseException {
      ExpressionConfiguration config = Mockito.mock(ExpressionConfiguration.class);
      Tokenizer tokenizer = new Tokenizer("\"test", config);
      tokenizer.parseStringLiteral();
    }
}
